type Page = 'radar' | 'technology' | 'suppliers' | 'tracking' | 'settings'
type FilterState = { q: string; uf: string; delivery: string; modality: string; max_capital: string; min_margin: string; days_remaining: string }
const money = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' })
const number = new Intl.NumberFormat('pt-BR')
const currency = (value: string | null | undefined) => value == null ? 'Não informado' : money.format(Number(value))
function decimal(value: string): string | null {
  const raw = value.trim().replace(/\s|R\$/g, '')
  if (!raw) return null
  const normalized = raw.includes(',') ? raw.replace(/\./g, '').replace(',', '.') : raw
  return /^\d+(\.\d{1,4})?$/.test(normalized) ? normalized : null
}
const failure = (error: unknown) => error instanceof Error ? error.message : 'Operação não concluída'
const synthetic = (control: string) => control.startsWith('SINTETICO-')

const statusLabel: Record<AnalysisStatus, string> = {
  new: 'Nova', in_analysis: 'Em análise', awaiting_quote: 'Aguardando cotação', viable: 'Viável',
  discarded: 'Descartada', preparing_proposal: 'Preparando proposta', proposal_sent: 'Proposta enviada',
  won: 'Vencida', lost: 'Perdida', contracted: 'Contratada', completed: 'Concluída',
}
const deliveryMeta = {
  A: { label: 'Remota favorável', cls: 'bg-[#E4EFEB] text-[#426F6A] border-[#D1E1DA]' },
  B: { label: 'Remota com condições', cls: 'bg-[#FAEEE5] text-[#935F4B] border-[#E5B79F]' },
  C: { label: 'Operação local', cls: 'bg-[#FAEEE5] text-[#935F4B] border-[#E5B79F]' },
  D: { label: 'Indeterminada', cls: 'bg-[#F3EADD] text-[#536672] border-[#E2D5C6]' },
}

function Badge({ children, className = '' }: { children: React.ReactNode; className?: string }) {
  return <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-xs font-semibold ${className}`}>{children}</span>
}

function Button({ children, className = '', loading, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { loading?: boolean }) {
  return <button className={`focus-ring inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-60 ${className}`} disabled={loading || props.disabled} {...props}>
    {loading && <LoaderCircle size={15} className="animate-spin" />}{children}
  </button>
}

