function StatCard({ label, value, icon, tone, note }: { label: string; value: number; icon: React.ReactNode; tone: string; note: string }) {
  return <div className="panel rounded-2xl p-5"><div className="mb-5 flex items-start justify-between"><span className="eyebrow">{label}</span><span className={`grid size-9 place-items-center rounded-xl ${tone}`}>{icon}</span></div><div className="text-3xl font-black tracking-tight text-[#405666]">{number.format(value)}</div><p className="mt-1 text-xs text-[#536874]">{note}</p></div>
}

function Filters({ filters, setFilters }: { filters: FilterState; setFilters: (x: FilterState) => void }) {
  const update = (key: string, value: string) => setFilters({ ...filters, [key]: value })
  return <div className="panel rounded-2xl p-4">
    <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-[2fr_repeat(5,1fr)]">
      <label className="relative"><Search size={16} className="absolute left-3 top-3 text-[#8A9695]"/><input value={filters.q} onChange={e => update('q', e.target.value)} placeholder="Produto, órgão ou palavra-chave" className="w-full rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[#79A49B]"/></label>
      <select value={filters.uf} onChange={e => update('uf', e.target.value)} className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] px-3 py-2.5 text-sm"><option value="">Todo o Brasil</option>{['SP','MG','RJ','PR','SC','RS','BA','PE','CE','GO','DF','ES','PA','AM'].map(x => <option key={x}>{x}</option>)}</select>
      <select value={filters.delivery} onChange={e => update('delivery', e.target.value)} className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] px-3 py-2.5 text-sm"><option value="">Toda logística</option><option value="A">Remota favorável</option><option value="B">Com condições</option><option value="C">Operação local</option><option value="D">Indeterminada</option></select>
      <select value={filters.modality} onChange={e => update('modality', e.target.value)} className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] px-3 py-2.5 text-sm"><option value="">Modalidade</option><option>Pregão</option><option>Dispensa</option><option>Concorrência</option><option>Credenciamento</option></select>
      <input value={filters.max_capital} onChange={e => update('max_capital', e.target.value)} inputMode="decimal" placeholder="Capital máximo" className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] px-3 py-2.5 text-sm"/>
      <input value={filters.min_margin} onChange={e => update('min_margin', e.target.value)} inputMode="decimal" placeholder="Margem mínima %" className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] px-3 py-2.5 text-sm"/>
      <select value={filters.days_remaining} onChange={e => update('days_remaining', e.target.value)} className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] px-3 py-2.5 text-sm"><option value="">Qualquer prazo</option><option value="3">Até 3 dias</option><option value="7">Até 7 dias</option><option value="15">Até 15 dias</option></select>
    </div>
  </div>
}

function Score({ value, provisional }: { value: string | null; provisional: boolean }) {
  const score = value ? Number(value) : null
  const cls = score == null ? 'bg-[#F3EADD] text-[#536874]' : score >= 70 ? 'bg-[#DDEAE4] text-[#426F6A]' : score >= 50 ? 'bg-[#F2DCCB] text-[#935F4B]' : 'bg-[#F3EADD] text-[#536672]'
  return <div className={`grid size-11 place-items-center rounded-xl text-sm font-black ${cls}`} title={provisional ? 'Pontuação provisória' : 'Pontuação confirmada'}>{score == null ? '—' : Math.round(score)}{provisional && score != null && <sup>*</sup>}</div>
}

function OpportunityTable({ rows, loading, openDetail }: { rows: Opportunity[]; loading: boolean; openDetail: (id: number) => void }) {
  if (loading) return <div className="panel grid min-h-64 place-items-center rounded-2xl"><div className="flex items-center gap-3 text-sm text-[#536874]"><LoaderCircle className="animate-spin"/> Carregando oportunidades reais…</div></div>
  if (!rows.length) return <div className="panel grid min-h-64 place-items-center rounded-2xl p-8 text-center"><div><FileSearch className="mx-auto mb-3 text-[#8A9695]" size={34}/><h3 className="font-bold">Nenhuma oportunidade encontrada</h3><p className="mt-1 text-sm text-[#536874]">Sincronize o PNCP ou ajuste os filtros.</p></div></div>
  return <div className="panel overflow-hidden rounded-2xl"><div className="scrollbar overflow-x-auto"><table className="w-full min-w-[1180px] border-collapse text-left"><thead><tr className="border-b border-[#E2D5C6] bg-[#F6EEE4]/80 text-[10px] uppercase tracking-wider text-[#536874]"><th className="px-5 py-3">Score</th><th className="px-3 py-3">Oportunidade</th><th className="px-3 py-3">Local</th><th className="px-3 py-3">Valor público</th><th className="px-3 py-3">Cotação</th><th className="px-3 py-3">Margem</th><th className="px-3 py-3">Entrega</th><th className="px-3 py-3">Prazo</th><th className="px-5 py-3"></th></tr></thead><tbody>
    {rows.map(row => { const d = row.delivery_classification ? deliveryMeta[row.delivery_classification] : deliveryMeta.D; const days = row.proposal_close_at ? differenceInCalendarDays(new Date(row.proposal_close_at), new Date()) : null; return <tr key={row.id} onClick={() => openDetail(row.id)} className="group cursor-pointer border-b border-[#EAE0D4] align-top transition last:border-0 hover:bg-[#E4EFEB]"><td className="px-5 py-4"><Score value={row.score} provisional={row.score_provisional}/></td><td className="max-w-[390px] px-3 py-4"><div className="line-clamp-2 text-sm font-bold leading-snug text-[#405666]">{row.object_description}</div><div className="mt-2 flex items-center gap-2 text-xs text-[#536874]"><Building2 size={13}/><span className="truncate">{row.organization_name}</span><span>·</span><span>{row.item_count} itens</span></div></td><td className="px-3 py-4 text-sm"><div className="flex items-center gap-1.5 font-semibold"><MapPin size={14} className="text-[#8A9695]"/>{row.municipality || '—'}</div><div className="mt-1 text-xs text-[#536874]">{row.uf || '—'} · {row.modality_name || '—'}</div></td><td className="px-3 py-4"><div className="text-sm font-bold">{row.estimated_total_value ? money.format(Number(row.estimated_total_value)) : 'Não divulgado'}</div><div className="mt-1 text-[10px] uppercase tracking-wide text-[#8A9695]">{row.estimated_total_value ? 'dado oficial' : 'desconhecido'}</div></td><td className="px-3 py-4 text-sm font-semibold">{row.lowest_quote ? money.format(Number(row.lowest_quote)) : <span className="font-normal text-[#8A9695]">Sem cotação</span>}</td><td className="px-3 py-4"><span className={`text-sm font-bold ${Number(row.simulated_margin) >= .1 ? 'text-[#426F6A]' : 'text-[#8A9695]'}`}>{row.simulated_margin ? `${(Number(row.simulated_margin) * 100).toFixed(1)}%` : '—'}</span>{row.required_capital && <div className="mt-1 text-[10px] text-[#8A9695]">Capital {money.format(Number(row.required_capital))}</div>}</td><td className="px-3 py-4"><Badge className={d.cls}>{d.label}</Badge>{row.remote_delivery_score != null && <div className="mt-1 text-[10px] text-[#8A9695]">{row.remote_delivery_score}/100</div>}</td><td className="px-3 py-4"><div className={`text-sm font-bold ${days != null && days <= 3 ? 'text-[#935F4B]' : ''}`}>{days == null ? '—' : days < 0 ? 'Encerrado' : `${days} dias`}</div><div className="mt-1 text-xs text-[#8A9695]">{row.proposal_close_at ? format(new Date(row.proposal_close_at), 'dd/MM · HH:mm') : 'sem data'}</div></td><td className="px-5 py-4"><ChevronRight className="text-[#B4C2C2] transition group-hover:translate-x-1 group-hover:text-[#426F6A]"/></td></tr> })}
  </tbody></table></div></div>
}

function RadarPage({ refresh, openDetail }: { refresh: number; openDetail: (id: number, itemId?: number, budget?: string | null) => void }) {
  const [budget, setBudget] = useState('5000')
  const [query, setQuery] = useState('')
  const [uf, setUf] = useState('')
  const [result, setResult] = useState<Recommendations | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [attempt, setAttempt] = useState(0)
  const [references, setReferences] = useState<Record<number, Opportunity>>({})
  const capital = decimal(budget)
  useEffect(() => { api.opportunities(new URLSearchParams({page_size:'100', open_only:'false'})).then(x => setReferences(Object.fromEntries(x.data.map(row => [row.id, row])))).catch(() => {}) }, [refresh])
  useEffect(() => {
    setResult(null)
    if (budget.trim() && capital === null) { setError('Informe um valor em reais válido, como 5.000,00.'); setLoading(false); return }
    const controller = new AbortController()
    const timer = setTimeout(() => {
      setLoading(true); setError('')
      api.recommendations({ available_capital: capital, q: query || null, uf: uf || null, page_size: 100 }, controller.signal)
        .then(setResult).catch(e => { if (!controller.signal.aborted) setError(failure(e)) })
        .finally(() => { if (!controller.signal.aborted) setLoading(false) })
    }, 300)
    return () => { clearTimeout(timer); controller.abort() }
  }, [budget, capital, query, uf, refresh, attempt])
  const group = (title: string, rows: RecommendationItem[], tone: string) => <section className="panel rounded-2xl p-5"><h3 className={`mb-3 font-extrabold ${tone}`}>{title} <span className="text-sm font-normal text-[#536874]">({rows.length})</span></h3>{rows.length ? <div className="space-y-3">{rows.map(row => { const reference=references[row.procurement_id]; return <button key={row.item_id} onClick={() => openDetail(row.procurement_id, row.item_id, capital)} className="w-full rounded-xl border border-[#E2D5C6] bg-[#FCF5EA] p-4 text-left hover:border-[#79A49B]"><div className="flex flex-wrap justify-between gap-2"><strong>Item {row.item_id} · {row.eligibility === 'viable' ? 'Viável sob premissas' : row.eligibility === 'blocked' ? 'Bloqueado' : 'Pendente'}</strong><span>{currency(row.required_capital)} de capital</span></div>{reference && <p className="mt-1 line-clamp-2 text-sm font-medium">{reference.object_description}</p>}<div className="mt-2 text-sm text-[#5F707A]">{row.explanation}</div><div className="mt-2 flex flex-wrap gap-3 text-xs text-[#536874]"><span>Saldo {currency(row.budget_remaining)}</span><span>Resultado {currency(row.estimated_result)}</span><span>{reference ? `${synthetic(reference.official_control_number) ? 'Sintético' : 'Arquivo oficial'} · ${reference.official_control_number}` : 'Origem: base local'}</span><span>{row.cost_basis === 'quoted' ? 'Custo: cotação' : row.cost_basis === 'manual_estimate' ? 'Custo: estimativa manual' : 'Custo desconhecido'}</span></div>{[...row.pending_checks, ...row.blockers].map(x => <div key={x} className="mt-1 text-xs text-[#935F4B]">{x}</div>)}</button> })}</div> : <p className="text-sm text-[#536874]">Nenhum item neste grupo para os filtros atuais.</p>}</section>
  return <main className="space-y-5 p-4 md:p-8"><section className="radar-intro"><div><span className="eyebrow">SILLO / Radar Licita</span><h2>Oportunidades com contexto para decidir.</h2><p>Explore o acervo de pregões históricos oficiais e avalie o capital disponível para cada item. O cruzamento com empresas está na aba Tecnologia.</p></div><div className="radar-intro-note"><ShieldCheck size={18}/><span>Os prazos deste acervo estão encerrados. Orçamento informado por você não é cotação de fornecedor.</span></div></section><section className="budget-panel panel rounded-2xl p-5 md:p-7"><span className="eyebrow">Simulação por item</span><h2 className="mt-2 text-xl font-extrabold">Quanto posso investir?</h2><p className="mt-1 text-sm text-[#536874]">Capital para executar um item. A busca não altera a configuração global.</p><div className="mt-4 flex flex-wrap gap-3"><input aria-label="Orçamento em reais" value={budget} onChange={e => setBudget(e.target.value)} inputMode="decimal" className="rounded-lg border border-[#D8CABB] px-3 py-2" placeholder="Ex.: 5.000,00"/>{['500','5000','10000'].map(x => <Button key={x} onClick={() => setBudget(x)} className="border border-[#D8CABB] bg-[#FCF5EA]">{money.format(Number(x))}</Button>)}<input aria-label="Termo da oportunidade" value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar item ou órgão" className="min-w-48 flex-1 rounded-lg border border-[#D8CABB] px-3 py-2"/><input aria-label="UF" value={uf} onChange={e => setUf(e.target.value.toUpperCase().slice(0,2))} placeholder="UF" className="w-20 rounded-lg border border-[#D8CABB] px-3 py-2"/></div></section>{loading && <p role="status">Buscando oportunidades…</p>}{error && <div role="alert" className="rounded-lg bg-[#FAEEE5] p-4 text-[#935F4B]">{error} <Button onClick={() => setAttempt(x => x + 1)} className="underline">Tentar novamente</Button></div>}{result && (result.recommendations.length + result.needs_analysis.length + result.outside_budget.length + result.blocked.length > 0) && <div className="space-y-4">{group('Elegíveis ordenadas', result.recommendations, 'text-[#426F6A]')}{group('Precisam de análise', result.needs_analysis, 'text-[#935F4B]')}{group('Excedem o orçamento', result.outside_budget, 'text-[#935F4B]')}{group('Bloqueadas', result.blocked, 'text-[#405666]')}</div>}{result && (result.recommendations.length + result.needs_analysis.length + result.outside_budget.length + result.blocked.length === 0) && <p className="rounded-xl border border-[#E2D5C6] bg-[#FCF5EA] p-4 text-sm text-[#5F707A]">Não há propostas abertas neste recorte histórico. Veja abaixo as contratações e empresas registradas.</p>}{Object.values(references).length > 0 && <section className="panel rounded-2xl p-5"><h3 className="text-lg font-extrabold">Contratações no acervo local ({Object.values(references).length})</h3><p className="mt-1 text-sm text-[#5F707A]">Registros oficiais disponíveis para abrir os itens e as empresas encontradas nos resultados. Os prazos deste recorte histórico estão encerrados.</p><div className="mt-4 grid gap-2 md:grid-cols-2">{Object.values(references).map(row => <button key={row.id} onClick={() => openDetail(row.id)} className="rounded-xl border border-[#E2D5C6] bg-[#FCF5EA] p-3 text-left hover:border-[#79A49B]"><strong className="line-clamp-2 text-sm">{row.object_description}</strong><span className="mt-1 block text-xs text-[#5F707A]">{row.organization_name} · {row.official_control_number}</span></button>)}</div></section>}</main>
}

function TechnologyPage({ openDetail }: { openDetail: (id: number, itemId?: number) => void }) {
  const [budgets, setBudgets] = useState('5.000; 10.000; 50.000')
  const [keyword, setKeyword] = useState('')
  const [uf, setUf] = useState('')
  const [horizon, setHorizon] = useState('14')
  const [historyStart, setHistoryStart] = useState('')
  const [historyEnd, setHistoryEnd] = useState('')
  const [result, setResult] = useState<TechnologySearchResult | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const search = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    const values = budgets.split(/[;\n]+/).map(decimal)
    if (!values.length || values.length > 8 || values.some(v => v === null)) {
      setError('Informe de 1 a 8 orçamentos válidos, separados por ponto e vírgula.')
      return
    }
    setBusy(true); setError(''); setResult(null)
    try {
      const next = await api.technologySearch({ budgets: values, keyword: keyword.trim() || null, uf: uf.trim() || null,
        open_horizon_days: Number(horizon), history_start: historyStart || null, history_end: historyEnd || null })
      setResult(next)
    } catch (e) { setError(failure(e)) } finally { setBusy(false) }
  }
  return <main className="space-y-5 p-4 md:p-8"><HistoricalTechnologyPanel />
    <section className="panel rounded-2xl p-5 md:p-6">
      <span className="eyebrow">Pesquisa de mercado público</span>
      <h2 className="mt-1 text-xl font-extrabold">Consulta adicional de propostas abertas</h2>
      <p className="mt-2 text-sm text-[#5F707A]">Consulta propostas abertas no PNCP e cruza descrições dos itens com resultados homologados de pregões eletrônicos. O preço do edital é estimativa pública; a empresa encontrada ainda precisa confirmar produto, condições e cotação.</p>
      <form onSubmit={search} className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
        <label className="text-xs font-bold text-[#536672] xl:col-span-2">Orçamentos disponíveis (R$, separados por ;)<input value={budgets} onChange={e=>setBudgets(e.target.value)} className="mt-1 w-full rounded-lg border border-[#D8CABB] px-3 py-2.5 text-sm font-normal" placeholder="5.000; 10.000; 50.000"/></label>
        <label className="text-xs font-bold text-[#536672]">Produto ou termo<input value={keyword} onChange={e=>setKeyword(e.target.value)} className="mt-1 w-full rounded-lg border border-[#D8CABB] px-3 py-2.5 text-sm font-normal" placeholder="Ex.: notebook"/></label>
        <label className="text-xs font-bold text-[#536672]">UF (opcional)<input value={uf} onChange={e=>setUf(e.target.value.toUpperCase().slice(0,2))} className="mt-1 w-full rounded-lg border border-[#D8CABB] px-3 py-2.5 text-sm font-normal" placeholder="Ex.: DF"/></label>
        <label className="text-xs font-bold text-[#536672]">Propostas até<select value={horizon} onChange={e=>setHorizon(e.target.value)} className="mt-1 w-full rounded-lg border border-[#D8CABB] px-3 py-2.5 text-sm font-normal"><option value="7">7 dias</option><option value="14">14 dias</option><option value="30">30 dias</option><option value="60">60 dias</option></select></label>
        <label className="text-xs font-bold text-[#536672]">Histórico de<input type="date" value={historyStart} onChange={e=>setHistoryStart(e.target.value)} className="mt-1 w-full rounded-lg border border-[#D8CABB] px-3 py-2.5 text-sm font-normal"/></label>
        <label className="text-xs font-bold text-[#536672]">Histórico até<input type="date" value={historyEnd} onChange={e=>setHistoryEnd(e.target.value)} className="mt-1 w-full rounded-lg border border-[#D8CABB] px-3 py-2.5 text-sm font-normal"/></label>
        <div className="flex items-end"><Button type="submit" loading={busy} className="w-full bg-[#426F6A] py-2.5 text-white"><Search size={15}/> Consultar PNCP</Button></div>
      </form>
      <p className="mt-3 text-xs text-[#536874]">O histórico padrão cobre uma semana cerca de três meses atrás. Ajuste as datas para procurar outras empresas. A consulta é limitada às primeiras páginas do PNCP.</p>
    </section>
    {busy && <div role="status" className="panel rounded-xl p-4 text-sm text-[#5F707A]"><LoaderCircle className="mr-2 inline animate-spin" size={16}/> Consultando propostas, itens e resultados públicos. A busca pode levar cerca de um minuto.</div>}
    {error && <div role="alert" className="rounded-xl border border-[#E5B79F] bg-[#FAEEE5] p-4 text-sm text-[#935F4B]">{error}</div>}
    {result && <>
      <section className="panel rounded-2xl p-5"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-extrabold">{result.opportunities.length} itens de tecnologia encontrados</h3><Badge className="border-[#E5B79F] bg-[#FAEEE5] text-[#935F4B]">{result.status === 'unavailable' ? 'Fonte indisponível' : 'Amostra parcial'}</Badge></div><p className="mt-2 text-sm text-[#5F707A]">{result.coverage.open_rows} propostas listadas · {result.coverage.open_purchases_checked} compras abertas examinadas · {result.coverage.historical_purchases_checked} compras históricas examinadas · {result.coverage.request_count} requisições</p><p className="mt-1 text-xs text-[#536874]">Histórico: {result.coverage.history_from} a {result.coverage.history_to}. Situação consultada em {new Date(result.searched_at).toLocaleString('pt-BR')}.</p><div className="mt-3 space-y-1">{result.limitations.map((item,i)=><p key={i} className="text-xs text-[#935F4B]">• {item}</p>)}</div></section>
      {result.opportunities.map(item => <article key={item.item_id} className="panel rounded-2xl p-5 md:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><span className="eyebrow">{item.categories.join(' · ')} · Item {item.item_number}</span><h3 className="mt-1 text-lg font-extrabold">{item.description}</h3><p className="mt-1 text-sm text-[#536874]">{item.organization} · {item.uf || 'UF não informada'} · {item.control_number}</p></div><div className="flex gap-2"><Button onClick={()=>openDetail(item.procurement_id,item.item_id)} className="border border-[#D8CABB] bg-[#FCF5EA]">Abrir análise</Button><a href={item.pncp_url} target="_blank" rel="noreferrer" className="focus-ring inline-flex items-center gap-1 rounded-lg border border-[#D8CABB] px-3 py-2 text-sm font-semibold">PNCP <ExternalLink size={14}/></a></div></div><p className="mt-3 text-xs text-[#536874]">Propostas até {item.proposal_close_at ? new Date(item.proposal_close_at).toLocaleString('pt-BR') : 'data não informada'}</p><div className="mt-4 rounded-xl bg-[#F6EEE4] p-4"><div className="text-sm font-bold">Estimativa pública do item: {currency(item.public_estimate)}</div><p className="mt-1 text-xs text-[#536874]">Base: {item.estimate_basis}. Comparação preliminar; custo de fornecimento, tributos, frete e capital necessário ainda não calculados.</p><div className="mt-3 flex flex-wrap gap-2">{item.budgets.map(b=><Badge key={b.amount} className={b.estimate_fits === true ? 'border-[#D1E1DA] bg-[#E4EFEB] text-[#426F6A]' : b.estimate_fits === false ? 'border-[#E5B79F] bg-[#FAEEE5] text-[#935F4B]' : 'border-[#E2D5C6] bg-[#FCF5EA] text-[#5F707A]'}>{currency(b.amount)}: {b.estimate_fits == null ? 'sem estimativa' : b.estimate_fits ? 'estimativa cabe' : 'estimativa supera'}</Badge>)}</div></div><div className="mt-5"><h4 className="text-sm font-extrabold">Empresas identificadas em pregões anteriores ({item.companies.length})</h4>{item.companies.length ? <div className="mt-3 grid gap-3 lg:grid-cols-2">{item.companies.map(company=><div key={company.tax_id} className="rounded-xl border border-[#E2D5C6] p-4"><div className="font-bold">{company.legal_name}</div><p className="mt-1 text-xs text-[#536874]">CNPJ {company.tax_id} · Compatibilidade técnica pendente</p><p className="mt-2 text-xs text-[#5F707A]">Termos em comum: {company.matched_terms.join(', ')}</p>{company.evidence.map((e,i)=><div key={i} className="mt-3 border-t border-[#EAE0D4] pt-3 text-xs"><p className="line-clamp-2 text-[#536672]">{e.description}</p><p className="mt-1 text-[#536874]">{e.result_date ? `Resultado ${String(e.result_date).slice(0,10)}` : 'Data não informada'} · Valor unitário homologado {currency(e.unit_price)}</p><a href={e.source_url} target="_blank" rel="noreferrer" className="mt-1 inline-flex items-center gap-1 font-semibold text-[#426F6A] underline">Ver resultado no PNCP <ExternalLink size={12}/></a></div>)}</div>)}</div> : <p className="mt-2 text-sm text-[#536874]">Nenhuma empresa comparável encontrada neste recorte histórico. Isso não exclui fornecedores aptos.</p>}</div></article>)}
      {!result.opportunities.length && <div className="panel rounded-2xl p-8 text-center text-sm text-[#5F707A]">Nenhum item de tecnologia apareceu na amostra. Tente outra UF, termo ou prazo.</div>}
    </>}
  </main>
}

function DetailDrawer({ id, initialItemId, budget, close, changed }: { id: number; initialItemId?: number; budget?: string | null; close: () => void; changed: () => void }) {
  const [data, setData] = useState<OpportunityDetail | null>(null)
  const [tab, setTab] = useState<'overview'|'items'|'evidence'|'partners'|'finance'>('overview')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  const [selectedItem, setSelectedItem] = useState(initialItemId || 0)
  const [statusBusy, setStatusBusy] = useState(false)
  const reload = useCallback(async () => { const next = await api.opportunity(id); setData(next); setSelectedItem(current => current && next.items.some(x => x.id === current) ? current : next.items[0]?.id || 0); changed() }, [id, changed])
  useEffect(() => { setData(null); setLoading(true); setError(''); setSelectedItem(initialItemId || 0); api.opportunity(id).then(next => { setData(next); setSelectedItem(current => current && next.items.some(x => x.id === current) ? current : next.items[0]?.id || 0) }).catch(e => setError(failure(e))).finally(() => setLoading(false)) }, [id, initialItemId])
  const processDocs = async () => { setBusy(true); try { await api.processDocuments(id); await reload() } catch(e) { setError(failure(e)) } finally { setBusy(false) } }
  const changeStatus = async (status: AnalysisStatus) => { setStatusBusy(true); setError(''); try { await api.updateStatus(id, status); await reload() } catch(e) { setError(failure(e)) } finally { setStatusBusy(false) } }
  return <div className="fixed inset-0 z-50 flex justify-end bg-[#405666]/50" onMouseDown={e => { if(e.currentTarget === e.target) close() }}><aside className="scrollbar h-full w-full max-w-4xl overflow-y-auto bg-[#F4EBDD] shadow-2xl"><div className="sticky top-0 z-10 border-b border-[#E2D5C6] bg-[#FCF5EA]/95 px-5 py-4 backdrop-blur"><div className="flex items-start justify-between gap-4"><div><span className="eyebrow">Detalhes da oportunidade</span><div className="mono mt-1 text-xs text-[#536874]">{data?.official_control_number || 'Carregando…'}</div></div><button onClick={close} className="rounded-lg border border-[#E2D5C6] bg-[#FCF5EA] p-2"><X size={19}/></button></div><nav className="mt-4 flex gap-1 overflow-x-auto">{([['overview','Resumo'],['items','Itens'],['evidence','Evidências'],['partners','Parceiros'],['finance','Simulador']] as const).map(([key,label]) => <button key={key} onClick={() => setTab(key)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-sm font-bold ${tab === key ? 'bg-[#405666] text-white' : 'text-[#536874] hover:bg-[#F3EADD]'}`}>{label}</button>)}</nav></div>
    {error && <div role="alert" className="m-5 rounded-lg bg-[#FAEEE5] p-3 text-sm text-[#935F4B]">{error} <button onClick={() => { setError(''); setLoading(true); api.opportunity(id).then(setData).catch(e => setError(failure(e))).finally(() => setLoading(false)) }} className="underline">Tentar novamente</button></div>}
    {loading ? <div className="grid h-80 place-items-center"><LoaderCircle className="animate-spin text-[#426F6A]"/></div> : data && <div className="space-y-5 p-5 md:p-7">
      <div className="rounded-lg border border-[#E5B79F] bg-[#FAEEE5] p-3 text-sm">{synthetic(data.official_control_number) ? 'Caso sintético de demonstração' : 'Arquivo oficial com datas originais'} · Referência: {data.official_control_number} · {data.proposal_close_at && new Date(data.proposal_close_at) < new Date() ? 'Prazo encerrado' : 'Confira o prazo no PNCP'}</div>
      <div className="panel flex flex-wrap items-center gap-3 rounded-xl p-4"><label className="text-sm font-bold">Próximo passo comercial <select disabled={statusBusy} value={data.analysis_status} onChange={e => changeStatus(e.target.value as AnalysisStatus)} className="ml-2 rounded-lg border border-[#D8CABB] p-2">{Object.entries(statusLabel).map(([value,label]) => <option key={value} value={value}>{label}</option>)}</select></label><span className="text-xs text-[#536874]">Registro manual; não comprova fato comercial.</span>{statusBusy && <LoaderCircle size={16} className="animate-spin"/>}</div>
      {(tab === 'partners' || tab === 'finance') && <label className="block text-sm font-bold">Item selecionado<select value={selectedItem} onChange={e => setSelectedItem(Number(e.target.value))} className="ml-2 max-w-full rounded-lg border border-[#D8CABB] p-2">{data.items.map(x => <option key={x.id} value={x.id}>{x.item_number} — {x.description.slice(0,70)}</option>)}</select></label>}
      {tab === 'overview' && <Overview data={data} processDocs={processDocs} busy={busy}/>} {tab === 'items' && <Items data={data}/>} {tab === 'evidence' && <EvidenceTab data={data} processDocs={processDocs} busy={busy}/>} {tab === 'partners' && selectedItem > 0 && <PartnersTab key={selectedItem} itemId={selectedItem} officialControlNumber={data.official_control_number} />} {tab === 'finance' && <FinanceTab key={selectedItem} data={data} itemId={selectedItem} budget={budget} reload={reload}/>} </div>}
  </aside></div>
}

function Overview({ data, processDocs, busy }: { data: OpportunityDetail; processDocs: () => void; busy: boolean }) {
  const delivery = data.delivery_requirement; const d = delivery ? deliveryMeta[delivery.classification] : deliveryMeta.D
  return <><section className="panel rounded-2xl p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div className="max-w-2xl"><div className="mb-3 flex flex-wrap gap-2"><Badge className="border-[#C9DEE2] bg-[#E7EFF1] text-[#405666]">{synthetic(data.official_control_number) ? 'Caso sintético' : 'Arquivo oficial'}</Badge><Badge className={d.cls}>{d.label}</Badge></div><h2 className="text-xl font-extrabold leading-snug text-[#405666]">{data.object_description}</h2><p className="mt-3 flex items-center gap-2 text-sm text-[#5F707A]"><Building2 size={16}/>{data.organization_name} · {data.municipality}/{data.uf}</p></div><Score value={data.latest_score?.score || null} provisional={data.latest_score?.provisional ?? true}/></div><div className="mt-6 grid gap-4 border-t border-[#EAE0D4] pt-5 sm:grid-cols-2 lg:grid-cols-4"><Info label="Valor estimado" value={data.estimated_total_value ? money.format(Number(data.estimated_total_value)) : 'Não divulgado'}/><Info label="Modalidade" value={data.modality_name || '—'}/><Info label="Encerra" value={data.proposal_close_at ? format(new Date(data.proposal_close_at), "dd/MM/yyyy 'às' HH:mm") : 'Não identificado'}/><Info label="Itens" value={String(data.items.length)}/></div></section>
    {data.latest_score && <section className="panel rounded-2xl p-6"><span className="eyebrow">Leitura do ranking</span><p className="mt-2 text-sm font-semibold leading-relaxed text-[#405666]">{data.latest_score.explanation}</p>{data.latest_score.blockers.length > 0 && <div className="mt-4 space-y-2">{data.latest_score.blockers.map(x => <div key={x} className="flex gap-2 rounded-lg bg-[#FAEEE5] p-3 text-sm text-[#935F4B]"><AlertCircle size={17} className="shrink-0"/>{x}</div>)}</div>}</section>}
    <section className="grid gap-4 md:grid-cols-2"><div className="panel rounded-2xl p-6"><div className="mb-4 flex items-center justify-between"><span className="eyebrow">Logística</span><Gauge size={18} className="text-[#8A9695]"/></div><div className="text-4xl font-black text-[#405666]">{delivery?.remote_delivery_score ?? '—'}<span className="text-sm text-[#8A9695]">/100</span></div><div className="mt-4 space-y-2 text-sm text-[#5F707A]">{delivery?.justifications.map(x => <div key={x} className="flex gap-2"><CheckCircle2 size={16} className="mt-0.5 shrink-0 text-[#426F6A]"/>{x}</div>) || <p>Processe os documentos para classificar.</p>}</div></div><div className="panel rounded-2xl p-6"><span className="eyebrow">Pendências humanas</span><div className="mt-4 space-y-2">{delivery?.pending_checks.map(x => <div key={x} className="flex gap-2 text-sm text-[#5F707A]"><AlertCircle size={16} className="mt-0.5 shrink-0 text-[#B47C65]"/>{x}</div>) || <p className="text-sm text-[#536874]">Análise documental ainda não executada.</p>}</div></div></section>
     <div className="flex flex-wrap gap-2">{!synthetic(data.official_control_number) && <a href={data.pncp_url} target="_blank" rel="noreferrer" className="focus-ring inline-flex items-center gap-2 rounded-lg bg-[#426F6A] px-4 py-2.5 text-sm font-bold text-white">Abrir no PNCP <ExternalLink size={15}/></a>}{!synthetic(data.official_control_number) && data.source_system_url && <a href={data.source_system_url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-lg border border-[#D8CABB] bg-[#FCF5EA] px-4 py-2.5 text-sm font-bold">Portal da disputa <ArrowUpRight size={15}/></a>}<span className="text-xs text-[#536874]">Leitura remota de documentos desativada na demonstração.</span></div></>
}

function Info({ label, value }: { label: string; value: string }) { return <div><div className="eyebrow">{label}</div><div className="mt-1 text-sm font-bold text-[#405666]">{value}</div></div> }
function Items({ data }: { data: OpportunityDetail }) { return <div className="space-y-3">{data.items.map(item => <div key={item.id} className="panel rounded-2xl p-5"><div className="flex items-start gap-4"><span className="mono grid size-9 shrink-0 place-items-center rounded-lg bg-[#F3EADD] text-xs font-bold">{item.item_number}</span><div className="flex-1"><h3 className="font-bold text-[#405666]">{item.description}</h3>{item.complementary_description && <p className="mt-1 text-sm text-[#536874]">{item.complementary_description}</p>}<div className="mt-3 flex flex-wrap gap-x-5 gap-y-2 text-xs text-[#536874]"><span>Quantidade <b className="text-[#405666]">{item.quantity || '—'} {item.unit || ''}</b></span><span>Unitário <b className="text-[#405666]">{item.unit_estimated_value ? money.format(Number(item.unit_estimated_value)) : 'não divulgado'}</b></span><span>Julgamento <b className="text-[#405666]">{item.judgment_criterion || 'não identificado'}</b></span></div></div></div></div>)}</div> }

function EvidenceTab({ data, processDocs, busy }: { data: OpportunityDetail; processDocs: () => void; busy: boolean }) {
  const evidence = data.documents.flatMap(d => d.extractions.map(e => ({...e, document: d.title, url: d.source_url})))
   return <div className="space-y-4"><div className="panel flex flex-wrap items-center justify-between gap-3 rounded-2xl p-5"><div><h3 className="font-extrabold">Documentos e rastreabilidade</h3><p className="mt-1 text-sm text-[#536874]">Cada conclusão conserva página, trecho e confiança. Leitura remota desativada na demonstração.</p></div></div>
    {data.documents.map(doc => <div key={doc.id} className="panel rounded-2xl p-5"><div className="flex items-start justify-between gap-3"><div><a href={doc.source_url} target="_blank" rel="noreferrer" className="font-bold text-[#405666] hover:text-[#426F6A]">{doc.title || `Documento ${doc.sequence}`}</a><div className="mt-1 text-xs text-[#536874]">{doc.document_type || 'Documento'} · {doc.processing_status}</div></div><Badge className={doc.processing_status === 'processed' ? 'border-[#D1E1DA] bg-[#E4EFEB] text-[#426F6A]' : doc.processing_status === 'failed' ? 'border-[#E5B79F] bg-[#FAEEE5] text-[#935F4B]' : 'border-[#E2D5C6] bg-[#F6EEE4] text-[#536672]'}>{doc.processing_status}</Badge></div>{doc.processing_error && <p className="mt-3 rounded-lg bg-[#FAEEE5] p-3 text-xs text-[#935F4B]">{doc.processing_error}</p>}</div>)}
    {evidence.length === 0 ? <div className="rounded-2xl border border-dashed border-[#D8CABB] p-10 text-center text-sm text-[#536874]">Nenhuma evidência extraída ainda.</div> : <div className="space-y-3">{evidence.map(e => <article key={e.id} className="panel rounded-2xl p-5"><div className="mb-3 flex flex-wrap items-center gap-2"><Badge className="border-[#D1E1DA] bg-[#E4EFEB] text-[#426F6A]">{e.field_name.replaceAll('_',' ')}</Badge><span className="text-xs font-bold text-[#536874]">página {e.page_number || '—'} · confiança {(Number(e.confidence)*100).toFixed(0)}%</span></div><blockquote className="border-l-2 border-[#79A49B] pl-4 text-sm leading-relaxed text-[#536672]">“{e.excerpt}”</blockquote><p className="mt-2 truncate text-xs text-[#8A9695]">{e.document}</p></article>)}</div>}</div>
}

function PartnersTab({ itemId, officialControlNumber }: { itemId: number; officialControlNumber: string }) {
  const [candidates, setCandidates] = useState<PartnerCandidate[]>([])
  const [search, setSearch] = useState<PartnerSearch | null>(null)
  const [query, setQuery] = useState(synthetic(officialControlNumber) ? '' : officialControlNumber)
  const [uf, setUf] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)
  useEffect(() => { setLoading(true); api.partnerCandidates(itemId).then(setCandidates).catch(e => setError(failure(e))).finally(() => setLoading(false)) }, [itemId])
  const run = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const fields = new FormData(event.currentTarget); setBusy(true); setError(''); try { const next = await api.partnerSearch(itemId, { query: query || null, uf: uf || null, published_from: String(fields.get('published_from') || '') || null, published_to: String(fields.get('published_to') || '') || null, max_results: 10 }); setSearch(next); setCandidates(next.candidates) } catch(e) { setError(failure(e)) } finally { setBusy(false) } }
  const promote = async (candidate: PartnerCandidate) => { setBusy(true); setError(''); try { const updated = await api.promoteCandidate(candidate.id); setCandidates(rows => rows.map(row => row.id === updated.id ? updated : row)) } catch(e) { setError(failure(e)) } finally { setBusy(false) } }
  return <div className="space-y-4"><section className="panel rounded-2xl p-5"><h3 className="font-extrabold">Buscar possíveis parceiros</h3><p className="mt-1 text-sm text-[#5F707A]">Resultados históricos de pregão identificam candidatas para investigação. Não comprovam estoque, interesse, contato ou cotação atual.</p><form onSubmit={run} className="mt-4 grid gap-3 sm:grid-cols-2"><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Termo ou número PNCP do item" aria-label="Termo ou número PNCP do item" className="rounded-lg border border-[#D8CABB] p-2"/><input value={uf} onChange={e => setUf(e.target.value.toUpperCase().slice(0,2))} placeholder="UF" aria-label="UF da busca" className="rounded-lg border border-[#D8CABB] p-2"/><label className="text-xs">Publicação de<input name="published_from" type="date" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label><label className="text-xs">Até<input name="published_to" type="date" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label><Button type="submit" loading={busy} className="bg-[#426F6A] text-white sm:col-span-2">Atualizar busca pública limitada</Button></form><p className="mt-2 text-xs text-[#536874]">Candidatas em cache aparecem abaixo sem consulta externa. Para este item oficial, o número PNCP já está preenchido e permite verificar sua cadeia pública específica. A atualização por termo consulta uma janela limitada e pode retornar recorte parcial.</p></section>
    {loading && <p role="status">Carregando cache de candidatas…</p>}{error && <div role="alert" className="rounded-lg bg-[#FAEEE5] p-3 text-[#935F4B]">{error} <button onClick={() => { setError(''); api.partnerCandidates(itemId).then(setCandidates).catch(e => setError(failure(e))) }} className="underline">Tentar cache novamente</button></div>}
    {search && <div className="rounded-lg bg-[#F3EADD] p-3 text-sm">Busca {search.status === 'unavailable' ? 'fonte indisponível' : search.status === 'success_empty' ? 'sem resultado no recorte' : search.status === 'success' ? 'com resultados' : 'parcial'}; {search.complete ? 'concluída' : 'recorte incompleto'} · {search.request_count} requisições · {new Date(search.queried_at.endsWith('Z') || /[+-]\d\d:\d\d$/.test(search.queried_at) ? search.queried_at : `${search.queried_at}Z`).toLocaleString('pt-BR', {timeZone:'America/Sao_Paulo'})}. {search.limitations.join(' ')}</div>}
    {!loading && candidates.length === 0 && <div className="panel rounded-xl p-5 text-sm text-[#5F707A]">Nenhuma candidata no cache deste item. Um resultado vazio cobre apenas a janela consultada.</div>}
    {candidates.map(candidate => <article key={candidate.id} className="panel rounded-2xl p-5"><div className="flex flex-wrap justify-between gap-2"><div><h4 className="font-extrabold">{candidate.legal_name}</h4><p className="mono text-xs">{candidate.tax_id}</p></div><Badge className="border-[#D8CABB]">{candidate.comparability === 'comparable' ? 'Comparável para investigação' : candidate.comparability === 'incompatible' ? 'Incompatível' : 'Comparabilidade pendente'}</Badge></div><p className="mt-2 text-sm">Evidências: {candidate.evidence_count} · Último registro: {candidate.last_observed_at || 'não informado'}</p>{candidate.reasons.map(reason => <p key={reason} className="mt-1 text-xs text-[#935F4B]">{reason}</p>)}{candidate.observations?.map((observation, index) => <div key={index} className="mt-3 rounded-lg bg-[#F6EEE4] p-3 text-xs"><p>{observation.description || 'Item não informado'} · {observation.result_date || 'data não informada'} · {observation.price_nature || 'natureza não informada'}</p><p>Preço histórico: {currency(observation.unit_price)}</p><a href={observation.source_url} target="_blank" rel="noreferrer" className="text-[#426F6A] underline">Evidência pública</a></div>)}{!candidate.observations?.length && <p className="mt-2 text-xs text-[#935F4B]">Sem registro de evidência exibível para esta candidata. Confira a fonte pública antes de qualquer decisão.</p>}<Button disabled={busy || candidate.supplier_id != null} onClick={() => promote(candidate)} className="mt-3 border border-[#D8CABB] bg-[#FCF5EA]">{candidate.supplier_id ? 'Candidata cadastrada' : 'Cadastrar candidata'}</Button></article>)}</div>
}

function FinanceTab({ data, itemId, budget, reload }: { data: OpportunityDetail; itemId: number; budget?: string | null; reload: () => Promise<void> }) {
  const item = data.items.find(x => x.id === itemId)
  const [suppliers, setSuppliers] = useState<Supplier[]>([])
  const [supplierId, setSupplierId] = useState(0)
  const [productId, setProductId] = useState(0)
  const [quoteId, setQuoteId] = useState(0)
  const [result, setResult] = useState<FinancialResult | null>(null)
  const [match, setMatch] = useState<{classification: string; reasons: string[]} | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [manualCost, setManualCost] = useState('')
  const [freight, setFreight] = useState('')
  const [freightKnown, setFreightKnown] = useState(false)
  const [taxConfirmed, setTaxConfirmed] = useState(false)
  const [taxRate, setTaxRate] = useState('')
  const [capital, setCapital] = useState(budget || '')
  const [productName, setProductName] = useState('')
  const [newQuotePrice, setNewQuotePrice] = useState('')
  const [quoteFreight, setQuoteFreight] = useState('')
  useEffect(() => { api.suppliers().then(setSuppliers).catch(e => setError(failure(e))) }, [itemId])
  const supplier = suppliers.find(x => x.id === supplierId)
  const product = supplier?.products.find(x => x.id === productId)
  const quotes = suppliers.flatMap(s => s.products.flatMap(p => p.quotes.map(q => ({...q, supplier: s.name, product: p.name})))).filter(q => q.procurement_item_id === itemId)
  const selectedQuote = quotes.find(x => x.id === quoteId)
  const analysis = data.item_analyses?.find(x => x.item_id === itemId)
  const saveQuote = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const quoteValid = String(new FormData(event.currentTarget).get('valid_until') || ''); if (!supplierId) { setError('Selecione um fornecedor cadastrado.'); return } setBusy(true); setError(''); try {
    let target = productId
    if (!target) { if (!productName.trim()) throw new Error('Informe o produto.'); const created = await api.createProduct(supplierId, { name: productName, specifications: {} }) as {id:number}; target = created.id }
    const price = decimal(newQuotePrice); if (!price || Number(price) <= 0) throw new Error('Preço de cotação inválido.')
    if (quoteFreight && decimal(quoteFreight) === null) throw new Error('Frete da cotação inválido.')
    const quote = await api.createQuote(target, { procurement_item_id: itemId, unit_price: price, quoted_at: new Date().toISOString().slice(0,10), valid_until: quoteValid || null, estimated_freight: quoteFreight ? decimal(quoteFreight) : null, freight_known: quoteFreight !== '' }) as {id:number}
    const assessed = await api.matchProduct(target, itemId) as {classification:string; reasons:string[]}; setMatch(assessed)
    const next = await api.suppliers(); setSuppliers(next); setQuoteId(quote.id); setManualCost(price); setFreight(quoteFreight); setFreightKnown(quoteFreight !== ''); await reload()
  } catch(e) { setError(failure(e)) } finally { setBusy(false) } }
  const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setBusy(true); setError(''); const f = new FormData(e.currentTarget)
    const price = selectedQuote?.unit_price || decimal(manualCost); const sale = decimal(String(f.get('sale_unit_price') || '')); const quantity = decimal(String(f.get('quantity') || ''))
    if (!price || !sale || !quantity) { setError('Quantidade, venda e aquisição precisam ser valores válidos.'); setBusy(false); return }
    const rate = decimal(taxRate); if (taxRate && (!rate || Number(rate) >= 100)) { setError('Tributos devem estar entre 0% e 99,99%.'); setBusy(false); return }
    if (capital && decimal(capital) === null) { setError('Capital inválido. Informe um valor em reais.'); setBusy(false); return }
    if (freight && decimal(freight) === null) { setError('Frete inválido.'); setBusy(false); return }
    for (const name of ['packaging','contingency']) { const value=String(f.get(name) || ''); if (value && decimal(value) === null) { setError(`Valor inválido em ${name}.`); setBusy(false); return } }
    try { const r = await api.simulate(itemId, { quantity, sale_unit_price: sale, acquisition_unit_cost: price, freight: selectedQuote?.estimated_freight ?? decimal(freight) ?? '0', packaging: decimal(String(f.get('packaging') || '')) ?? '0', insurance: '0', tax_rate: rate ? String(Number(rate)/100) : '0', financial_cost: '0', installation_cost: '0', contingency: decimal(String(f.get('contingency') || '')) ?? '0', payment_days: 30, available_capital: decimal(capital), target_margin_rate: '0.15', freight_known: selectedQuote ? selectedQuote.freight_known : freightKnown, taxes_confirmed: taxConfirmed, supplier_quote_id: quoteId || null }); setResult(r); await reload() } catch(err) { setError(failure(err)) } finally { setBusy(false) }
  }
  if(!item) return <div className="panel rounded-2xl p-8 text-center">Esta contratação ainda não possui itens sincronizados.</div>
  return <div className="space-y-5">{error && <div role="alert" className="rounded-lg bg-[#FAEEE5] p-3 text-[#935F4B]">{error}</div>}<div className="panel rounded-2xl p-5"><h3 className="font-extrabold">Produto e cotação atual</h3><p className="mt-1 text-sm text-[#536874]">Referência pública do item: {currency(item.unit_estimated_value)} por {item.unit || 'unidade'}. Não é custo de aquisição.</p><form onSubmit={saveQuote} className="mt-4 grid gap-3 sm:grid-cols-2"><select value={supplierId} onChange={e => {setSupplierId(Number(e.target.value)); setProductId(0)}} className="rounded-lg border border-[#D8CABB] p-2"><option value={0}>Selecione fornecedor cadastrado</option>{suppliers.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select><select value={productId} onChange={e => setProductId(Number(e.target.value))} className="rounded-lg border border-[#D8CABB] p-2"><option value={0}>Novo produto</option>{supplier?.products.map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select>{!productId && <input value={productName} onChange={e => setProductName(e.target.value)} placeholder="Descrição do produto" className="rounded-lg border border-[#D8CABB] p-2"/>}<input value={newQuotePrice} onChange={e => setNewQuotePrice(e.target.value)} placeholder="Preço atual unitário" inputMode="decimal" className="rounded-lg border border-[#D8CABB] p-2"/><input value={quoteFreight} onChange={e => setQuoteFreight(e.target.value)} placeholder="Frete cotado (vazio = desconhecido)" inputMode="decimal" className="rounded-lg border border-[#D8CABB] p-2"/><label className="text-xs">Válida até<input name="valid_until" type="date" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label><Button type="submit" loading={busy} className="bg-[#405666] text-white sm:col-span-2">Salvar cotação para este item e avaliar compatibilidade</Button></form>{match && <p className="mt-3 text-sm">Compatibilidade: {match.classification}. {match.reasons.join(' ')}</p>}</div>
    <div className="grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><form onSubmit={submit} className="panel rounded-2xl p-6"><h3 className="text-lg font-extrabold">Simulação financeira</h3><p className="mt-2 text-xs text-[#5F707A]">Os campos abaixo iniciam uma nova simulação. A elegibilidade exibida ao lado pertence ao último cálculo salvo e pode usar outro capital ou cotação.</p><label className="mt-4 block text-sm">Cotação do item<select value={quoteId} onChange={e => {const id=Number(e.target.value); setQuoteId(id); const q=quotes.find(x=>x.id===id); if(q){setManualCost(q.unit_price); setFreight(q.estimated_freight || ''); setFreightKnown(q.freight_known)} setResult(null)}} className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"><option value={0}>Sem cotação vigente selecionada — análise pendente</option>{quotes.map(x => <option key={x.id} value={x.id}>{x.supplier} · {x.product} · {currency(x.unit_price)} · validade {x.valid_until || 'desconhecida'}</option>)}</select></label>{selectedQuote && <p className="mt-2 text-xs text-[#935F4B]">Aquisição {currency(selectedQuote.unit_price)}; frete {currency(selectedQuote.estimated_freight)}; validade {selectedQuote.valid_until || 'não informada'}. Qualquer divergência manual precisa ser revista.</p>}<div className="mt-4 grid gap-3 sm:grid-cols-2"><Field name="quantity" label="Quantidade" defaultValue={item.quantity || ''}/><Field name="sale_unit_price" label="Venda unitária" defaultValue={item.unit_estimated_value || ''}/><label className="text-xs font-bold">Aquisição manual<input disabled={!!selectedQuote} value={manualCost} onChange={e => setManualCost(e.target.value)} inputMode="decimal" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label><label className="text-xs font-bold">Frete total<input disabled={!!selectedQuote} value={freight} onChange={e => setFreight(e.target.value)} inputMode="decimal" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label><Field name="packaging" label="Embalagem"/><Field name="contingency" label="Reserva"/><label className="text-xs font-bold">Tributos (%)<input value={taxRate} onChange={e => setTaxRate(e.target.value)} inputMode="decimal" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label><label className="text-xs font-bold">Capital disponível<input value={capital} onChange={e => setCapital(e.target.value)} inputMode="decimal" className="mt-1 w-full rounded-lg border border-[#D8CABB] p-2"/></label></div><label className="mt-4 flex gap-2 text-sm"><input type="checkbox" checked={freightKnown} disabled={!!selectedQuote} onChange={e => setFreightKnown(e.target.checked)}/> Frete conhecido e confirmado</label><label className="mt-2 flex gap-2 text-sm"><input type="checkbox" checked={taxConfirmed} onChange={e => setTaxConfirmed(e.target.checked)}/> Tributos conferidos para esta operação</label><Button type="submit" loading={busy} className="mt-5 w-full bg-[#426F6A] text-white">Calcular cenário</Button></form><div className="space-y-3">{result ? <><Metric label="Resultado estimado" value={currency(result.estimated_result)}/><Metric label="Capital necessário" value={currency(result.required_capital)}/><Metric label="Margem" value={`${(Number(result.margin_rate)*100).toFixed(1)}%`}/><div className="panel rounded-xl p-4 text-sm"><b>{result.assumptions_complete ? 'Premissas completas para avaliação' : 'Premissas incompletas: manter pendência'}</b><pre className="mt-2 overflow-x-auto text-xs">{JSON.stringify(result.sensitivity, null, 2)}</pre></div></> : <div className="panel rounded-xl p-5 text-sm text-[#536874]">Selecione a cotação e confirme as premissas. Trocar de item limpa o resultado.</div>}{analysis && <div className="panel rounded-xl p-4 text-sm"><b>Elegibilidade do item: {analysis.eligibility}</b><p>{analysis.explanation}</p>{[...analysis.pending_checks, ...analysis.blockers].map(x => <p key={x} className="mt-1 text-[#935F4B]">{x}</p>)}<pre className="mt-2 overflow-x-auto text-xs">{JSON.stringify(analysis.components, null, 2)}</pre></div>}</div></div></div>
}
function Field({ name, label, defaultValue = '' }: { name: string; label: string; defaultValue?: string }) { return <label className="text-xs font-bold text-[#5F707A]">{label}<input required={['quantity','sale_unit_price','acquisition_unit_cost'].includes(name)} name={name} defaultValue={defaultValue} inputMode="decimal" className="mt-1 w-full rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm font-normal"/></label> }
function Metric({ label, value }: { label: string; value: string }) { return <div className="panel rounded-2xl p-5"><div className="eyebrow">{label}</div><div className="mt-2 text-2xl font-black text-[#405666]">{value}</div></div> }

function SuppliersPage({ refresh }: { refresh: number }) {
  const [suppliers, setSuppliers] = useState<Supplier[]>([]); const [show, setShow] = useState(false); const [quoteSupplier, setQuoteSupplier] = useState<number | null>(null); const [busy, setBusy] = useState(false)
  const [error,setError] = useState('')
  const load = useCallback(() => api.suppliers().then(setSuppliers).catch(e => setError(failure(e))), []); useEffect(() => { load() }, [load, refresh])
  const create = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setBusy(true); setError(''); const f = Object.fromEntries(new FormData(e.currentTarget)); try { await api.createSupplier(f); setShow(false); await load() } catch(e) {setError(failure(e))} finally { setBusy(false) } }
  const createProductAndQuote = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); if (!quoteSupplier) return; setBusy(true); setError(''); const f = Object.fromEntries(new FormData(e.currentTarget)); try { const product = await api.createProduct(quoteSupplier, { name: f.product_name, brand: f.brand || null, model: f.model || null, sku: f.sku || null, technical_description: f.technical_description || null, specifications: {}, direct_shipping: f.direct_shipping === 'on' }) as { id: number }; await api.createQuote(product.id, { unit_price: decimal(String(f.unit_price)) ?? f.unit_price, quoted_at: new Date().toISOString().slice(0,10), valid_until: f.valid_until || null, dispatch_days: f.dispatch_days ? Number(f.dispatch_days) : null, estimated_freight: f.freight ? decimal(String(f.freight)) : null, freight_known: Boolean(f.freight), direct_shipping: f.direct_shipping === 'on' }); setQuoteSupplier(null); await load() } catch(e) {setError(failure(e))} finally { setBusy(false) } }
  const csvImport = async (e: React.ChangeEvent<HTMLInputElement>) => { const file=e.target.files?.[0]; if(file){setBusy(true);setError(''); try{await api.importCsv(file);await load()}catch(e){setError(failure(e))}finally{setBusy(false)}} }
  return <main className="p-4 md:p-8">{error && <div role="alert" className="mb-4 rounded-lg bg-[#FAEEE5] p-3 text-sm text-[#935F4B]">{error} <button onClick={() => {setError('\''); load()}} className="underline">Tentar novamente</button></div>}<div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><span className="eyebrow">Base comercial</span><h2 className="mt-1 text-xl font-extrabold">{suppliers.length} fornecedores cadastrados</h2></div><div className="flex gap-2"><label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-[#D8CABB] bg-[#FCF5EA] px-3.5 py-2 text-sm font-bold"><Upload size={15}/> Importar CSV<input type="file" accept=".csv" className="hidden" onChange={csvImport}/></label><Button onClick={() => setShow(!show)} className="bg-[#426F6A] text-white"><Plus size={15}/> Novo fornecedor</Button></div></div>
    {show && <form onSubmit={create} className="panel mb-5 grid gap-3 rounded-2xl p-5 md:grid-cols-5"><input name="name" required placeholder="Nome do fornecedor" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm md:col-span-2"/><input name="tax_id" placeholder="CNPJ" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="origin_uf" maxLength={2} placeholder="UF" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><Button type="submit" loading={busy} className="bg-[#405666] text-white">Salvar</Button></form>}
    {quoteSupplier && <form onSubmit={createProductAndQuote} className="panel mb-5 rounded-2xl p-5"><div className="mb-4 flex items-center justify-between"><div><span className="eyebrow">Produto e cotação</span><h3 className="mt-1 font-extrabold">{suppliers.find(s => s.id === quoteSupplier)?.name}</h3></div><button type="button" onClick={() => setQuoteSupplier(null)}><X size={18}/></button></div><div className="grid gap-3 md:grid-cols-4"><input name="product_name" required placeholder="Produto" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm md:col-span-2"/><input name="brand" placeholder="Marca" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="model" placeholder="Modelo" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="sku" placeholder="SKU" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="unit_price" required inputMode="decimal" placeholder="Preço unitário" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="freight" inputMode="decimal" placeholder="Frete estimado" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="dispatch_days" inputMode="numeric" placeholder="Expedição (dias)" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="valid_until" type="date" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm"/><input name="technical_description" placeholder="Descrição técnica" className="rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm md:col-span-2"/><label className="flex items-center gap-2 text-sm text-[#5F707A]"><input name="direct_shipping" type="checkbox"/> Envio direto disponível</label><Button type="submit" loading={busy} className="bg-[#405666] text-white">Salvar cotação</Button></div></form>}
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{suppliers.map(s => <div key={s.id} className="panel rounded-2xl p-5"><div className="flex items-start justify-between"><span className="grid size-10 place-items-center rounded-xl bg-[#DDEAE4] text-[#426F6A]"><Building2 size={19}/></span><Badge className="border-[#E2D5C6] bg-[#F6EEE4] text-[#5F707A]">{s.origin_uf || 'UF —'}</Badge></div><h3 className="mt-4 font-extrabold">{s.name}</h3><p className="mt-1 text-xs text-[#536874]">{s.tax_id || 'CNPJ não informado'}</p><div className="mt-5 border-t border-[#EAE0D4] pt-4"><div className="flex justify-between text-sm"><span className="text-[#536874]">Produtos</span><b>{s.products.length}</b></div><div className="mt-2 flex justify-between text-sm"><span className="text-[#536874]">Cotações</span><b>{s.products.reduce((n,p)=>n+p.quotes.length,0)}</b></div>{s.products.slice(0,2).map(p => <div key={p.id} className="mt-3 rounded-lg bg-[#F6EEE4] p-3 text-xs"><div className="font-bold text-[#405666]">{p.name}</div><div className="mt-1 text-[#536874]">{p.quotes[0] ? money.format(Number(p.quotes[0].unit_price)) : 'Sem cotação'}</div></div>)}<Button onClick={() => setQuoteSupplier(s.id)} className="mt-4 w-full border border-[#D8CABB] bg-[#FCF5EA]"><Plus size={14}/> Produto e cotação</Button></div></div>)}{!suppliers.length && <div className="panel col-span-full grid min-h-64 place-items-center rounded-2xl text-center"><div><Users className="mx-auto mb-3 text-[#8A9695]"/><h3 className="font-bold">Nenhum fornecedor comercial confirmado</h3><p className="mt-1 max-w-xl text-sm text-[#536874]">As empresas de resultados históricos aparecem na aba Tecnologia como possíveis parceiras. Cadastre aqui somente após validar condições e obter dados comerciais reais.</p></div></div>}</div></main>
}

function TrackingPage({ refresh, openDetail }: { refresh: number; openDetail: (id: number) => void }) {
  const [rows,setRows]=useState<Opportunity[]>([])
  const [error,setError]=useState('')
  const [attempt,setAttempt]=useState(0)
  useEffect(()=>{const p=new URLSearchParams({page_size:'100',open_only:'false'});api.opportunities(p).then(x=>setRows(x.data)).catch(e=>setError(failure(e)))},[refresh,attempt])
  const columns = Object.keys(statusLabel) as AnalysisStatus[]
  return <main className="scrollbar overflow-x-auto p-4 md:p-8"><p className="mb-4 text-sm text-[#5F707A]">Estados de acompanhamento registrados manualmente. Viabilidade calculada por item aparece no detalhe.</p>{error && <div role="alert" className="mb-4 rounded-lg bg-[#FAEEE5] p-3">{error} <button onClick={()=>setAttempt(x=>x+1)} className="underline">Tentar novamente</button></div>}<div className="flex min-w-[1200px] gap-4">{columns.map(status => <section key={status} className="w-72 shrink-0"><div className="mb-3 flex items-center justify-between"><h3 className="text-sm font-extrabold">{statusLabel[status]}</h3><Badge className="border-[#E2D5C6] bg-[#FCF5EA] text-[#5F707A]">{rows.filter(x=>x.analysis_status===status).length}</Badge></div><div className="space-y-3">{rows.filter(x=>x.analysis_status===status).map(x=><button onClick={()=>openDetail(x.id)} key={x.id} className="panel w-full rounded-xl p-4 text-left"><div className="line-clamp-3 text-sm font-bold">{x.object_description}</div><div className="mt-2 text-xs text-[#536874]">{x.official_control_number}</div></button>)}</div></section>)}</div></main>
}

function SettingsPage() {
  const [saved,setSaved]=useState(false); const [initial,setInitial]=useState<Record<string,any>>({}); useEffect(()=>{api.settings().then(setInitial)},[])
  const weights = initial.score_weights || {}
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));await api.saveSettings({origin_uf:f.origin_uf||null,available_capital:f.available_capital?Number(f.available_capital):null,minimum_margin:f.minimum_margin?Number(f.minimum_margin)/100:null,maximum_delivery_days:f.maximum_delivery_days?Number(f.maximum_delivery_days):null,minimum_preparation_days:f.minimum_preparation_days?Number(f.minimum_preparation_days):null,tax_rate:f.tax_rate?Number(f.tax_rate)/100:null,prefer_remote_delivery:true,preferred_categories:String(f.preferred_categories||'').split(',').map(x=>x.trim()).filter(Boolean),score_weights:{margin:Number(f.weight_margin)/100,remote_delivery:Number(f.weight_remote)/100,capital:Number(f.weight_capital)/100,supplier:Number(f.weight_supplier)/100,operations:Number(f.weight_operations)/100,information:Number(f.weight_information)/100}});setSaved(true);setTimeout(()=>setSaved(false),2500)}
  return <main className="p-4 md:p-8"><form onSubmit={submit} className="panel mx-auto max-w-4xl rounded-2xl p-6 md:p-8"><div className="flex items-start justify-between"><div><span className="eyebrow">Premissas da operação</span><h2 className="mt-1 text-xl font-extrabold">Critérios de decisão</h2><p className="mt-1 text-sm text-[#536874]">Esses valores alimentam elegibilidade e ranking.</p></div><SlidersHorizontal className="text-[#8A9695]"/></div><div className="mt-7 grid gap-5 md:grid-cols-2"><Field name="origin_uf" label="UF de origem" defaultValue={initial.origin_uf||''}/><Field name="available_capital" label="Capital disponível" defaultValue={initial.available_capital||''}/><Field name="minimum_margin" label="Margem mínima (%)" defaultValue={initial.minimum_margin?String(Number(initial.minimum_margin)*100):'10'}/><Field name="tax_rate" label="Premissa de tributos (%)" defaultValue={initial.tax_rate?String(Number(initial.tax_rate)*100):''}/><Field name="maximum_delivery_days" label="Prazo máximo de entrega" defaultValue={initial.maximum_delivery_days||''}/><Field name="minimum_preparation_days" label="Dias mínimos para preparar proposta" defaultValue={initial.minimum_preparation_days||'3'}/><label className="text-xs font-bold text-[#5F707A] md:col-span-2">Categorias preferidas<input name="preferred_categories" defaultValue={(initial.preferred_categories||[]).join(', ')} placeholder="informática, escritório, limpeza" className="mt-1 w-full rounded-lg border border-[#E2D5C6] px-3 py-2.5 text-sm font-normal"/></label></div><div className="mt-8 border-t border-[#E2D5C6] pt-6"><span className="eyebrow">Pesos do score (%)</span><div className="mt-4 grid gap-4 sm:grid-cols-3"><Field name="weight_margin" label="Margem" defaultValue={String(Number(weights.margin ?? .30)*100)}/><Field name="weight_remote" label="Entrega remota" defaultValue={String(Number(weights.remote_delivery ?? .25)*100)}/><Field name="weight_capital" label="Capital" defaultValue={String(Number(weights.capital ?? .15)*100)}/><Field name="weight_supplier" label="Fornecedor" defaultValue={String(Number(weights.supplier ?? .15)*100)}/><Field name="weight_operations" label="Prazo/operação" defaultValue={String(Number(weights.operations ?? .10)*100)}/><Field name="weight_information" label="Informação" defaultValue={String(Number(weights.information ?? .05)*100)}/></div><p className="mt-3 text-xs text-[#536874]">Mantenha a soma em 100%. O backend usa os valores como pesos configuráveis e conserva a decomposição do score.</p></div><div className="mt-7 flex items-center gap-3"><Button type="submit" className="bg-[#426F6A] text-white"><Settings size={15}/> Salvar configurações</Button>{saved && <span className="flex items-center gap-1.5 text-sm font-semibold text-[#426F6A]"><CheckCircle2 size={16}/> Salvo</span>}</div></form></main>
}

export default function App() {
  const [page,setPage]=useState<Page>(() => new URLSearchParams(window.location.search).get('demo') === 'historico' ? 'technology' : 'radar'); const [menu,setMenu]=useState(false); const [refresh,setRefresh]=useState(0); const [detail,setDetail]=useState<{id:number; itemId?:number; budget?:string|null}|null>(null)
  const openDetail=(id:number,itemId?:number,budget?:string|null)=>setDetail({id,itemId,budget})
  const changed=useCallback(()=>setRefresh(x=>x+1),[])
  return <div className="shell"><Sidebar page={page} setPage={setPage} open={menu} close={()=>setMenu(false)}/><div className="min-h-screen lg:pl-64"><Header page={page} toggleMenu={()=>setMenu(true)}/>{page==='radar'&&<RadarPage refresh={refresh} openDetail={openDetail}/>} {page==='technology'&&<TechnologyPage openDetail={openDetail}/>} {page==='suppliers'&&<SuppliersPage refresh={refresh}/>} {page==='tracking'&&<TrackingPage refresh={refresh} openDetail={openDetail}/>} {page==='settings'&&<SettingsPage/>}</div>{detail!=null&&<DetailDrawer id={detail.id} initialItemId={detail.itemId} budget={detail.budget} close={()=>setDetail(null)} changed={changed}/>}</div>
}




